import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, mul, add } from 'three/tsl';
import { gsap } from 'gsap';
import * as primitives from '@/primitives';
import * as text from '@/text';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  // Root container
  const root = new Group();
  root.position.set(0, -0.3, 0);
  root.rotation.set(0, 0, 0);
  root.scale.set(1, 1, 1);

  // Atlas region (fallback to full texture if not provided)
  const atlas = config.atlasRegion || { width: 512, height: 320 };
  const aspect = atlas.width / atlas.height;
  const planeWidth = aspect; // unit height = 1
  const planeHeight = 1;

  // Geometry
  const geometry = new PlaneGeometry(planeWidth, planeHeight);
  // UV transform to sample the atlas region
  const uvNode = uv()
    .mul(add(uv().scale(1 / atlas.width), uv().scale(1 / atlas.height)))
    .add(uv().scale(atlas.x / atlas.width).add(uv().scale(atlas.y / atlas.height)));

  // Material (basic node material)
  const material = new MeshBasicNodeMaterial({
    color: 0xffffff,
    map: null,
    // Apply UV offset/scale via node material's map node
    // The node material automatically uses the provided UV node when a map is set
    // We attach the UV node to the material's map node
    // Note: three/tsl nodes are attached via material.mapNode = textureNode; material.uvNode = uvNode;
  });
  // Attach UV node to material (node material API)
  material.uvNode = uvNode;

  // Mesh
  const mesh = new Mesh(geometry, material);
  root.add(mesh);

  // Load texture asynchronously; material will be updated when ready
  let texture = null;
  ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
    texture = tex;
    material.map = texture;
    material.needsUpdate = true;
  });

  // No primitives to apply for this node
  // No text content to render

  // Event handlers container (empty for this static node)
  root.userData.handlers = {};

  // Cleanup routine
  root.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (texture) texture.dispose();
    // No GSAP timelines were created, but ensure any future ones are killed
    gsap.globalTimeline.clear();
  };

  return root;
}
